#!/usr/bin/env python3
"""Build offline template comparison and working design mixer; no external requests."""
from pathlib import Path
import argparse, base64, html, json
from render_resume import load_tokens,load_themes,make_html

CSS='''*{box-sizing:border-box}body{margin:0;background:#f4f4ef;color:#202d30;font:14px/1.65 'Noto Sans CJK SC','Microsoft YaHei',Arial,sans-serif}main{max-width:1460px;margin:auto;padding:45px 36px 65px}.masthead{border-top:3px solid #233638;padding:22px 0 26px;display:flex;justify-content:space-between;gap:30px;align-items:end}.kicker{font-size:11px;letter-spacing:.14em;font-weight:750;color:#486a68}h1{font-family:'Noto Serif CJK SC',Georgia,serif;font-size:35px;line-height:1.35;margin:6px 0 0}h2{font-size:21px;margin:0 0 6px}p{margin:0}.sub{color:#536563;max-width:760px;line-height:1.85}.version{font-size:11px;white-space:nowrap;color:#536563}.editor{display:grid;grid-template-columns:300px 1fr;gap:24px;margin:28px 0 42px;align-items:start}.controls{padding:22px;background:#fff;border:1px solid #cfd5d4;position:sticky;top:12px}.controls h2{font-size:17px}.field{margin-top:18px}label{display:block;font-size:12px;font-weight:650;margin-bottom:5px}select{width:100%;font:inherit;padding:10px 9px;border:1px solid #bdc9c5;border-radius:4px;background:white;color:#233638}.help{font-size:11px;color:#536563;line-height:1.7;margin-top:7px}.swatches{display:flex;gap:5px;margin-top:9px}.swatch{height:27px;flex:1;border:1px solid #0002;border-radius:3px}.action{cursor:pointer;border:1px solid #243d41;background:#243d41;color:white;font-size:12px;font-weight:600;padding:10px 13px;border-radius:4px;line-height:1.5}.action.secondary{background:#fff;color:#243d41}.actions{margin-top:20px;display:flex;gap:7px;flex-wrap:wrap}.stage{border:1px solid #cfd5d4;background:#e5e8e7;padding:18px;min-width:0}.stage-header{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:15px;font-size:12px;color:#40524f}.preview{position:relative;overflow:hidden;margin:auto;max-width:794px;background:white;box-shadow:0 4px 22px #26343420}.preview iframe{position:absolute;top:0;left:0;border:0;transform-origin:top left;background:white}.stage-foot{font-size:11px;color:#536563;margin-top:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:21px;margin-top:20px}.card{border:1px solid #cbd4d1;background:white;min-width:0;cursor:pointer;text-align:left;padding:0;display:block;color:inherit;font-family:inherit;transition:border-color .2s,box-shadow .2s}.card:hover,.card:focus-visible{border-color:#335957;box-shadow:0 4px 17px #2634341c}.card.selected{outline:2px solid #335957;outline-offset:2px}.card .sheet{background:#e5e7e7;padding:12px;min-height:180px;display:flex;align-items:start;justify-content:center}.card img{display:block;width:100%;height:auto;box-shadow:0 2px 8px #1a252529}.mono-mode .card img:not([data-neutral]){filter:grayscale(1)}.card .title{font-weight:700;font-size:14px;display:block;margin-bottom:4px}.card .text{padding:12px 14px 16px}.card .desc{display:block;font-size:11px;color:#536563;line-height:1.65}.tagline{font-size:10px;display:block;color:#365957;margin-bottom:5px}.toggle{display:flex;align-items:center;gap:8px;color:#334b48;font-size:12px}.toggle input{width:16px;height:16px}.sectionhead{display:flex;align-items:center;justify-content:space-between;gap:12px}.rule{margin-top:26px;padding-top:16px;border-top:1px solid #cbd4d1;font-size:11px;color:#536563}.status{font-size:11px;color:#47635d;margin-top:10px;min-height:18px}@media(max-width:1050px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.editor{grid-template-columns:255px 1fr}}@media(max-width:750px){main{padding:22px 16px}.masthead{display:block}h1{font-size:26px}.editor{grid-template-columns:1fr}.controls{position:static}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.stage{padding:10px}.sectionhead{display:block}.sectionhead .toggle{margin-top:9px}}'''
JS=r'''
const $=id=>document.getElementById(id);
const layout=$('layout'),palette=$('palette'),font=$('font'),rhythm=$('rhythm'),paper=$('paper'),frame=$('frame'),viewport=$('viewport');
function fill(el,list){el.replaceChildren();for(const [id,t] of list){const op=document.createElement('option');op.value=id;op.textContent=t;el.appendChild(op);}}
fill(layout,DATA.layouts.map(v=>[v.id,v.title]));fill(palette,Object.entries(DATA.palettes).map(([k,v])=>[k,v.title]));fill(font,Object.entries(DATA.fonts).map(([k,v])=>[k,v.title]));fill(rhythm,Object.entries(DATA.rhythms).map(([k,v])=>[k,v.title]));fill(paper,[['A4','A4 · 210 × 297 mm'],['Letter','US Letter']]);
let active, rendered='';
function setPreset(id,scroll=false){active=DATA.layouts.find(v=>v.id===id);layout.value=id;palette.value=active.palette_id;font.value=active.font_id;rhythm.value=active.rhythm_id;paper.value='A4';update();if(scroll)$('mixer').scrollIntoView({behavior:'smooth',block:'start'});}
function config(){return {version:DATA.version,theme:layout.value,palette:palette.value,font:font.value,rhythm:rhythm.value,page:paper.value}}
function tokens(c){const p=DATA.palettes[c.palette],f=DATA.fonts[c.font],s=DATA.rhythms[c.rhythm],v={};for(const [k,value] of Object.entries(p))if(k!=='title')v[k.replaceAll('_','-')]=value;Object.assign(v,{'font-body':f.body,'font-head':f.heading,'head-weight':f.weight,'body-size':s.body_pt+'pt','leading':s.line_height,'head-size':s.heading_pt+'pt','section-gap':s.section_gap_pt+'pt','entry-gap':s.entry_gap_pt+'pt','title-gap':s.title_gap_pt+'pt','bullet-gap':s.bullet_gap_pt+'pt','gutter':s.gutter_mm+'mm','margin':s.margin_mm+'mm','page-width':c.page==='A4'?'210mm':'215.9mm','page-height':c.page==='A4'?'297mm':'279.4mm'});return ':root{'+Object.entries(v).map(([k,value])=>'--'+k+':'+value+';').join('')+'}';}
function update(){const t=DATA.layouts.find(v=>v.id===layout.value);if(t.ats_candidate){palette.value='paper';font.value='neutral';}palette.disabled=font.disabled=t.ats_candidate;
 const c=config(),s=DATA.rhythms[c.rhythm],p=DATA.palettes[c.palette]; rendered=HTMLS[c.theme].replace(/\/\*TOKENS_START\*\/[\s\S]*?\/\*TOKENS_END\*\//,'/*TOKENS_START*/'+tokens(c)+'/*TOKENS_END*/').replace(/\/\*PAGE_START\*\/[\s\S]*?\/\*PAGE_END\*\//, '/*PAGE_START*/@page{size:'+c.page+';margin:'+s.margin_mm+'mm}/*PAGE_END*/');
 frame.srcdoc=rendered;$('summary').textContent=t.title+' · '+p.title+' · '+DATA.fonts[c.font].title;$('description').textContent=t.description;$('rhythmhelp').textContent=`正文 ${s.body_pt} pt · CSS行高 ${s.line_height} · 章节间距 ${s.section_gap_pt} pt · 页边距 ${s.margin_mm} mm`;$('channel').textContent=t.ats_candidate?'ATS 基线 · 配色及字体已锁定（不代表通过实际系统）':'真人阅读版 · 请另存机器投递稿（如需要）';
 $('swatches').replaceChildren();for(const k of ['paper','ink','accent','highlight','band']){let a=document.createElement('div');a.className='swatch';a.style.background=p[k];a.title=k+' '+p[k];$('swatches').append(a)}
 for(const c of document.querySelectorAll('.card'))c.classList.toggle('selected',c.dataset.theme===layout.value);$('status').textContent='';scale();}
function scale(){const w=paper.value==='A4'?794:816;const h=paper.value==='A4'?1123:1056;const avail=Math.min(viewport.parentElement.clientWidth-36,794);const z=Math.max(.2,avail/w);viewport.style.width= Math.round(w*z)+'px';let docHeight=h+44;frame.style.width=w+'px';frame.style.height=docHeight+'px';try{docHeight=Math.max(docHeight,frame.contentDocument.documentElement.scrollHeight);}catch{}viewport.style.height=Math.round(docHeight*z)+'px';frame.style.width=w+'px';frame.style.height=docHeight+'px';frame.style.transform='scale('+z+')'}
frame.addEventListener('load',scale);window.addEventListener('resize',scale);layout.addEventListener('change',()=>setPreset(layout.value));for(const e of [palette,font,rhythm,paper])e.addEventListener('change',update);for(const card of document.querySelectorAll('.card'))card.addEventListener('click',()=>setPreset(card.dataset.theme,true));$('mono').addEventListener('change',()=>{$('gallery').classList.toggle('mono-mode',$('mono').checked);for(const img of document.querySelectorAll('.card img[data-neutral]'))img.src=$('mono').checked?img.dataset.neutral:img.dataset.original;});$('reset').addEventListener('click',()=>setPreset(layout.value));
function save(text,name,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}
$('save-html').addEventListener('click',()=>{save(rendered,'resume-'+layout.value+'.html','text/html');$('status').textContent='已发起 HTML 下载；正式投递前请检查打印页数。'});$('save-config').addEventListener('click',()=>{save(JSON.stringify(config(),null,2),'resume-design-config.json','application/json');$('status').textContent='已发起配置下载；可将 JSON 给 Agent 复用。'});
setPreset('book-editorial');
'''

def safe_json(x):return json.dumps(x,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
def main():
    p=argparse.ArgumentParser();p.add_argument('--input',required=True);p.add_argument('--output',required=True);p.add_argument('--thumbnail-dir',help='Optional existing PNGs from actual A4 rendering; each filename is theme ID');p.add_argument('--neutral-dir',help='Optional actual previews rendered with identical paper, neutral font, balanced rhythm');a=p.parse_args();d=json.loads(Path(a.input).read_text(encoding='utf-8'));dest=Path(a.output).resolve();target=dest.parent/'previews';target.mkdir(parents=True,exist_ok=True)
    t=load_tokens();htmls={};cards=[]
    for v in t['layouts']:
        sid=v['id'];r=make_html(d,v);htmls[sid]=r;(target/(sid+'.html')).write_text(r,encoding='utf-8')
        thumb=Path(a.thumbnail_dir)/(sid+'.png') if a.thumbnail_dir else None
        if thumb and thumb.is_file():
            uri='data:image/png;base64,'+base64.b64encode(thumb.read_bytes()).decode('ascii');neutral=Path(a.neutral_dir)/(sid+'.png') if a.neutral_dir else None;extra=''
            if neutral and neutral.is_file():
                nu='data:image/png;base64,'+base64.b64encode(neutral.read_bytes()).decode('ascii');extra=f' data-original="{uri}" data-neutral="{nu}"'
            image=f'<img alt="{html.escape(v["title"])}实际A4样例" src="{uri}"{extra} loading="lazy">'
        else:
            image=f'<iframe title="{html.escape(v["title"])}" srcdoc="{html.escape(r,quote=True)}" style="width:794px;height:1123px;transform:scale(.29);transform-origin:top left;border:0;pointer-events:none;position:absolute;top:0;left:0"></iframe>'
        style='' if thumb and thumb.is_file() else 'style="position:relative;height:330px;overflow:hidden"';cards.append(f'<button class="card" data-theme="{sid}" type="button"><span class="sheet" {style}>{image}</span><span class="text"><span class="tagline">{html.escape(v["recommended_for"])}</span><span class="title">{html.escape(v["title"])}</span><span class="desc">{html.escape(v["description"])}</span></span></button>')
    body=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resume Narrative Studio / Design Lab 1.2</title><style>{CSS}</style></head><body><main><header class="masthead"><div><div class="kicker">RESUME NARRATIVE STUDIO / DESIGN LAB</div><h1>简历视觉实验室</h1></div><div class="version">V1.2 · 12 LAYOUTS / 12 PALETTES / 7 TYPE SYSTEMS</div></header><p class="sub">从真实的版面结构出发，在安全的字号、间距和对比度规范下混搭字体与颜色。演示资料为虚构履历，所有操作离线执行。默认样例可打印一页；更长的内容可以自然分页。</p><section class="editor" id="mixer"><aside class="controls"><h2>自由混搭</h2><p class="help">先选布局，再选择视觉语言。ATS 基线锁定为清晰单栏。</p><div class="field"><label for="layout">版面结构</label><select id="layout"></select><p id="description" class="help"></p></div><div class="field"><label for="palette">配色系统</label><select id="palette"></select><div class="swatches" id="swatches"></div></div><div class="field"><label for="font">字体组合</label><select id="font"></select></div><div class="field"><label for="rhythm">阅读节奏</label><select id="rhythm"></select><p id="rhythmhelp" class="help"></p></div><div class="field"><label for="paper">纸张</label><select id="paper"></select></div><div class="actions"><button class="action" id="save-html">导出当前 HTML</button><button class="action secondary" id="save-config">导出配置</button><button class="action secondary" id="reset">恢复预设</button></div><div class="status" id="status" aria-live="polite"></div></aside><div class="stage"><div class="stage-header"><span id="summary"></span><span>实时预览</span></div><div class="preview" id="viewport"><iframe id="frame" title="当前简历设计预览"></iframe></div><p class="stage-foot" id="channel"></p></div></section><div class="sectionhead"><div><h2>12 种结构预设</h2><p class="sub">点击任意效果进入混搭；开启统一印刷令牌对照，比较相同中性色、字体与间距下的构图（未提供中性缩略图时使用灰度）。</p></div><label class="toggle"><input type="checkbox" id="mono"> 统一令牌 / 灰度比较</label></div><section class="grid" id="gallery">{''.join(cards)}</section><p class="rule">所有风格共享全局阅读规范。字体使用设备上的授权字体及回退字体；未内嵌字体。导出的 HTML 是视觉起点，实际 PDF / Word 及 ATS 投递须另做渲染与顺序核验。</p></main><script>const DATA={safe_json(t)};const HTMLS={safe_json(htmls)};{JS}</script></body></html>'''
    # Place the gallery before the editor for immediate structure comparison. Clicking a card opens the editor.
    start=body.index('<section class="editor"');end=body.index('<div class="sectionhead"',start);tail=body.index('<p class="rule"',end);body=body[:start]+body[end:tail]+body[start:end]+body[tail:]
    dest.write_text(body,encoding='utf-8');print('Gallery and',len(cards),'previews built:',dest)
if __name__=='__main__': main()
